});

const a = BABYLON.MeshBuilder.CreateBox('a', { size: 0.5 });
const b = BABYLON.MeshBuilder.CreateBox('b', { size: 0.5 });
b.position.x = 1;
const c = BABYLON.MeshBuilder.CreateSphere('c', { diameter: 0.6 });
