const merged = BABYLON.Mesh.MergeMeshes([a, b, c]); // ONE mesh now
merged.name = 'mergedMesh';

// scene.createDefaultCameraOrLight(true, false, true);
scene.createDefaultLight();

const camera = new BABYLON.UniversalCamera(
  'uCamera', new BABYLON.Vector3(0, 1, -5), scene
);
camera.attachControl();
camera.setTarget(BABYLON.Vector3.Zero()); // look at the center

scene.collisionsEnabled = true;
scene.gravity = new BABYLON.Vector3(0, -0.5, 0);

camera.checkCollisions = true;   // can’t pass through meshes
camera.applyGravity = true;      // falls down
camera.ellipsoid = new BABYLON.Vector3(0.5, 1, 0.5); // body size

ground.checkCollisions = true;   // meshes must opt in too

const camera = new BABYLON.ArcRotateCamera(
  'arCamera', 0, 0, 10, BABYLON.Vector3.Zero(), scene
);
camera.attachControl();
camera.setPosition(new BABYLON.Vector3(0, 0, -10)); // or place it with coordinates

const camera = new BABYLON.FollowCamera(
  'fCamera', new BABYLON.Vector3(0, 5, -10), scene
);
camera.lockedTarget = box; // the mesh to follow

// move the box and watch the camera chase it
scene.registerBeforeRender(function () {
  box.position.x += 0.02;
});

const camera = new BABYLON.FlyCamera(
  'flyCamera', new BABYLON.Vector3(0, 2, -10), scene
);
camera.attachControl();

camera.mode = BABYLON.Camera.ORTHOGRAPHIC_CAMERA;
camera.orthoLeft = -5;
camera.orthoRight = 5;
camera.orthoTop = 5;
camera.orthoBottom = -5;

scene.activeCamera.detachControl();
scene.activeCamera = arcCamera;
arcCamera.attachControl(canvas, true);

const sphere = BABYLON.MeshBuilder.CreateSphere('', { diameter: 0.5 });
const sphereMaterial = new BABYLON.StandardMaterial();
sphere.material = sphereMaterial;

sphereMaterial.ambientColor = new BABYLON.Color3(0, 1, 1);
scene.ambientColor = new BABYLON.Color3(0, 0.5, 0.5);

sphereMaterial.emissiveColor = new BABYLON.Color3(0.5, 0, 0.5);
sphereMaterial.alpha = 0.5;       // 1 = solid
sphereMaterial.wireframe = true;

sphereMaterial.diffuseTexture = new BABYLON.Texture('images/earth.jpg');

// shows even without light:
