const box = BABYLON.MeshBuilder.CreateBox('', {
  size: 0.3,
  faceUV: [
    new BABYLON.Vector4(0, 0, 1 / 6, 1),
    new BABYLON.Vector4(1 / 6, 0, 2 / 6, 1),
