utilLayer.dispose(); // remove it when you are done

scene.registerBeforeRender(function () {
  box.rotation.y += 0.01;
});

scene.registerBeforeRender(function () {
  box.rotation.y += 0.001 * engine.getDeltaTime(); // 1 radian per second
});

BABYLON.Animation.CreateAndStartAnimation(
  'slide', box, 'position.x',
  30,      // frames per second
  60,      // total frames (60 / 30 = 2 seconds)
  -2, 2    // from value, to value
);

const animation = new BABYLON.Animation(
  'spin', 'rotation.y', 30,
  BABYLON.Animation.ANIMATIONTYPE_FLOAT,
  BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
);

animation.setKeys([
  { frame: 0, value: 0 },
  { frame: 30, value: Math.PI },
  { frame: 60, value: Math.PI * 2 }
]);

box.animations = [];
box.animations.push(animation);

scene.beginAnimation(box, 0, 60, true);

// number
BABYLON.Animation.CreateAndStartAnimation('a', box, 'rotation.y', 30, 60, 0, Math.PI * 2);

// Vector3 (position, scaling)
BABYLON.Animation.CreateAndStartAnimation('b', box, 'position', 30, 60,
  new BABYLON.Vector3(-2, 0, 0), new BABYLON.Vector3(2, 0, 0));

// Color3 (material color)
BABYLON.Animation.CreateAndStartAnimation('c', material, 'diffuseColor', 30, 60,
  BABYLON.Color3.Red(), BABYLON.Color3.Blue());

const mode = BABYLON.Animation;
// mode.ANIMATIONLOOPMODE_CONSTANT : play once, then stay at the end
// mode.ANIMATIONLOOPMODE_CYCLE    : jump back to the start and repeat
// mode.ANIMATIONLOOPMODE_YOYO     : play forward, then backward, forever
// mode.ANIMATIONLOOPMODE_RELATIVE : repeat, adding the change each time

const ease = new BABYLON.BounceEase();
ease.setEasingMode(BABYLON.EasingFunction.EASINGMODE_EASEOUT);
animation.setEasingFunction(ease);

const anim = scene.beginAnimation(box, 0, 60, true);

anim.pause();
anim.restart();
anim.speedRatio = 2;  // twice as fast
anim.stop();

anim.onAnimationEndObservable.add(function () {
