const hit = scene.pick(scene.pointerX, scene.pointerY);

if (hit.hit) {
  console.log(hit.pickedMesh.name); // which mesh
  console.log(hit.pickedPoint);     // exact 3D point
  console.log(hit.distance);        // distance from the camera
}

scene.onPointerDown = function () {
  const hit = scene.pick(scene.pointerX, scene.pointerY);

  if (hit.hit && hit.pickedMesh.name === 'shadowCaster') {
    hit.pickedMesh.material = new BABYLON.StandardMaterial();
    hit.pickedMesh.material.diffuseColor = BABYLON.Color3.Random();
  }
};

ground.isPickable = false; // rays pass through it

// or only accept meshes that return true
const hit = scene.pick(scene.pointerX, scene.pointerY, function (mesh) {
  return mesh.name !== 'myGround';
});

scene.onPointerDown = function () {
  const hit = scene.pick(scene.pointerX, scene.pointerY);

  if (hit.hit) {
    const dot = BABYLON.MeshBuilder.CreateSphere('dot', { diameter: 0.2 });
    dot.position = hit.pickedPoint.clone();
  }
};

scene.onPointerMove = function () {
  const hit = scene.pick(scene.pointerX, scene.pointerY);
  canvas.style.cursor = hit.hit ? 'pointer' : 'default';
};

const origin = new BABYLON.Vector3(0, 5, 0);
const direction = new BABYLON.Vector3(0, -1, 0); // straight down
const ray = new BABYLON.Ray(origin, direction, 10); // length 10

BABYLON.RayHelper.CreateAndShow(ray, scene, new BABYLON.Color3(1, 1, 0));

const hit = scene.pickWithRay(ray);
if (hit.hit) {
  console.log('The ray hit', hit.pickedMesh.name);
}

