walk.play(true);

BABYLON.SceneLoader.ImportMeshAsync('', 'models/', 'Fox.glb', scene, function (event) {
  if (event.lengthComputable) {
    console.log(Math.round((event.loaded / event.total) * 100) + '%');
  }
});

BABYLON.SceneLoader.ImportMesh('', 'models/', 'Fox.glb', scene, function (meshes) {
  meshes[0].scaling.setAll(0.5);
});

const bgMusic = new BABYLON.Sound(
  'backgroundMusic',
  'audio/piano.wav',
  scene,
  null,
  { autoplay: true, loop: true }
);

bgMusic.play();
bgMusic.pause();
bgMusic.stop();

scene.enablePhysics(
  new BABYLON.Vector3(0, -9.81, 0),
  new BABYLON.CannonJSPlugin()
);

ground.physicsImpostor = new BABYLON.PhysicsImpostor(
  ground, BABYLON.PhysicsImpostor.BoxImpostor,
  { mass: 0, restitution: 0.5 }, scene
);

const ball = BABYLON.MeshBuilder.CreateSphere('ball', { diameter: 1 });
ball.position.y = 4;

ball.physicsImpostor = new BABYLON.PhysicsImpostor(
  ball, BABYLON.PhysicsImpostor.SphereImpostor,
  { mass: 1, restitution: 0.7 }, scene
);

ball.physicsImpostor.applyImpulse(
  new BABYLON.Vector3(5, 0, 0),    // direction and strength
  ball.getAbsolutePosition()       // where it is pushed
);

ball.physicsImpostor.setLinearVelocity(new BABYLON.Vector3(0, 5, 0)); // set speed

ball.physicsImpostor.registerOnPhysicsCollide(
  ground.physicsImpostor,
  function (main, collided) {
    console.log('The ball hit the ground');
  }
);

for (let i = 0; i < 5; i++) {
  const b = BABYLON.MeshBuilder.CreateBox('b' + i, { size: 0.5 });
  b.position.set(0, 0.25 + i * 0.5, 0);
  b.physicsImpostor = new BABYLON.PhysicsImpostor(
    b, BABYLON.PhysicsImpostor.BoxImpostor, { mass: 1 }, scene
  );
}

const particles = new BABYLON.ParticleSystem('particles', 2000, scene); // name, max count, scene
particles.particleTexture = new BABYLON.Texture(
  'https://playground.babylonjs.com/textures/flare.png', scene
);
particles.emitter = new BABYLON.Vector3(0, 0, 0);
particles.start();

particles.direction1 = new BABYLON.Vector3(-0.3, 1, -0.3);
particles.direction2 = new BABYLON.Vector3(0.3, 1, 0.3);
particles.minEmitPower = 1;                          // slowest start speed
particles.maxEmitPower = 2;                          // fastest start speed
particles.gravity = new BABYLON.Vector3(0, -2, 0);   // pulls them down
particles.minAngularSpeed = 0;                       // spin speed range
particles.maxAngularSpeed = Math.PI;
particles.updateSpeed = 0.01;                        // overall speed of time

particles.start();
particles.stop();

particles.targetStopDuration = 2; // stop by itself after 2 seconds
particles.disposeOnStop = true;   // and remove itself when it stops

particles.dispose();              // remove it right now

const fire = new BABYLON.ParticleSystem('fire', 1500, scene);
fire.particleTexture = new BABYLON.Texture('https://playground.babylonjs.com/textures/flare.png', scene);
fire.emitter = new BABYLON.Vector3(0, 0, 0);
fire.minEmitBox = new BABYLON.Vector3(-0.2, 0, -0.2);
fire.maxEmitBox = new BABYLON.Vector3(0.2, 0, 0.2);
fire.color1 = new BABYLON.Color4(1, 0.6, 0.1, 1);
fire.color2 = new BABYLON.Color4(1, 0.2, 0, 1);
fire.colorDead = new BABYLON.Color4(0, 0, 0, 0);
fire.minSize = 0.1;
fire.maxSize = 0.4;
fire.minLifeTime = 0.3;
fire.maxLifeTime = 1;
fire.emitRate = 300;
fire.blendMode = BABYLON.ParticleSystem.BLENDMODE_ONEONE;
fire.direction1 = new BABYLON.Vector3(-0.3, 1, -0.3);
fire.direction2 = new BABYLON.Vector3(0.3, 1, 0.3);
fire.gravity = new BABYLON.Vector3(0, 1, 0);
fire.start();

scene.onPointerDown = function () {
  const hit = scene.pick(scene.pointerX, scene.pointerY);

  if (hit.hit) {
    particles.emitter = hit.pickedPoint.clone();
    particles.manualEmitCount = 50;
    particles.start();
  }
};

